import{z as n,x as A,o,c as p,q as l,j as s,D as e,d as r,s as i,S as t,b as E}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"缓存无关结构","description":"","frontmatter":{"title":"缓存无关结构","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/cache-oblivious.md","filePath":"cs/cache-oblivious.md","lastUpdated":1791063341000}'),d={name:"cs/cache-oblivious.md"};function c(m,a,h,u,D,_){const B=A("Mermaid");return o(),p("div",null,[a[2]||(a[2]=l('<h1 id="缓存无关结构" tabindex="-1">缓存无关结构 <a class="header-anchor" href="#缓存无关结构" aria-label="Permalink to &quot;缓存无关结构&quot;">​</a></h1><div class="epigraph"><p>算法不读缓存行长度 $B$ 与容量 $M$；用递归对半，使任意 $B$ 下 I/O 仍接近已知 $B$ 的最优。</p><footer>—— 据 Frigo, Leiserson, Prokop and Ramachandran, Cache-Oblivious Algorithms, FOCS 1999；Prokop, Cache-Oblivious Algorithms, 硕士论文 1999 整理</footer></div><p><a href="/cs/functional-queue">上一课</a> 谈持久，不谈层次存储。<a href="/cs/locality-principle">局部性</a> 与 <a href="/cs/btree-external">B+</a> 显式按页 \\(B\\) 调扇出。本课不 CAS。缺口是缓存无关：van Emde Boas 布局的树、递归矩阵乘与排序，分析用理想缓存模型。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>外存/缓存最优常依赖 \\(B\\)（块大小）。部署时 \\(B\\) 多层不同（L1/L2/页）。缓存无关：代码无 \\(B,M\\)，但 I/O 次数与「知道 \\(B\\) 的最优」同阶（常差对数因子内）。静态搜索树：按 van Emde Boas 递归把子树连续存放，查找 I/O \\(O(\\log_B n)\\)。缺口是<strong>用递归空间布局代替调参 \\(B\\)</strong>。</p><p><span class="marginnote">术语翻译：「缓存无关」不是「不理会缓存」，而是「代码不读缓存参数」——不写死行大小 \\(B\\) 与容量 \\(M\\)，靠递归对半让结构在每一层存储上都自动长出一个恰好装下的切片。</span></p><p><span class="marginnote">Frigo et al., <em>FOCS</em>, 1999。理想缓存：全相联、最优替换；与真实 LRU 差一个常数因子定理（在一定条件下）。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>分治规模降到适合未知 \\(M\\) 的切点自然出现。funnel sort、缓存无关 B 树（缓冲树的亲戚）点名。实现：建静态树时中序不连续而 vEB 序连续。</p><p><span class="marginnote">直觉类比：vEB 布局像目录套目录的书——全书分章、每章分节且各段连续排版；无论你的书签能夹住几页，总有一级划分恰好放得下，翻页（块传输）次数都最少。</span></p>',10)),(o(),s(t,null,{default:e(()=>[i(B,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20REC%5B%22%E9%80%92%E5%BD%92%E5%AF%B9%E5%8D%8A%20%2F%20vEB%20%E5%88%87%22%5D%20--%3E%20LAY%5B%22%E5%AD%90%E6%A0%91%E8%BF%9E%E7%BB%AD%E5%AD%98%E6%94%BE%22%5D%0A%20%20LAY%20--%3E%20IO%5B%22%E4%BB%BB%E6%84%8F%20B%3A%20%E6%8E%A5%E8%BF%91%20log_B%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,"与 LSM：LSM 显式多层 \\(T\\)、容量，缓存有关且面向写。下一课把 LSM 当结构本体，不是数据库课重写 WAL。",-1)),a[4]||(a[4]=E("h2",{id:"机制",tabindex:"-1"},[r("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=E("p",null,"模型不计计算只计块传输。对扫描已最优的数组，缓存无关帮不上更多。并发与持久可叠，但分析分开。不要把「无关」理解成「不吃缓存」——恰恰是为了吃未知的那一层。",-1)),(o(),s(t,null,{default:e(()=>[i(B,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20BS%5B%22%E6%99%AE%E9%80%9A%E4%BA%8C%E5%8F%89%E6%9F%A5%E6%89%BE%3A%20%E6%AF%8F%E5%B1%82%E8%AE%BF%E5%AD%98%E4%B8%80%E6%AC%A1%22%5D%20--%3E%20L20%5B%22%E7%99%BE%E4%B8%87%E9%94%AE%E7%BA%A6%2020%20%E6%AC%A1%E8%AE%BF%E5%AD%98%22%5D%0A%20%20VEB%5B%22vEB%20%E5%B8%83%E5%B1%80%3A%20%E9%A1%B6%E5%B1%82%E5%88%87%E6%88%90%E5%B9%B3%E6%96%B9%E6%A0%B9%E7%BA%A7%E5%AD%90%E6%A0%91%22%5D%20--%3E%20CONT%5B%22%E6%AF%8F%E7%89%87%E8%BF%9E%E7%BB%AD%E5%AD%98%E6%94%BE%22%5D%0A%20%20CONT%20--%3E%20FIT%5B%22%E6%9F%90%E5%B1%82%E5%AD%90%E6%A0%91%E6%81%B0%E5%A5%BD%E8%A3%85%E8%BF%9B%E7%BC%93%E5%AD%98%22%5D%0A%20%20FIT%20--%3E%20L4%5B%22%E7%99%BE%E4%B8%87%E9%94%AE%E7%BA%A6%204%20%E6%AC%A1%E5%9D%97%E4%BC%A0%E8%BE%93%22%5D%0A%20%20BT%5B%22%E5%AF%B9%E7%85%A7%20B%20%E6%A0%91%3A%20%E6%89%87%E5%87%BA%E6%98%BE%E5%BC%8F%E5%8F%96%20B%22%5D%20--%3E%20L4%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=l('<p><span class="marginnote">数字实例：一百万键、\\(B{=}64\\)：普通二叉查找要 \\(\\log_2 10^6 \\approx 20\\) 次访存；vEB 布局每步带走 \\(\\log_2 64 = 6\\) 层，共约 \\(\\log_{64} 10^6 \\approx 3.3\\) 次块传输。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不证全部替换定理。GPU 共享内存是另一层次参数。写优化的日志结构合并是 LSM，显式分层。</p><p>后课默认：只读递归布局可缓存无关。写多读少的外存字典用 LSM 树形态。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>缓存无关：代码不参数化 \\(B\\)，递归布局接近最优 I/O。</li><li>vEB 布局是搜索树实例。</li><li>下一课 LSM：面向写的多层有序串。</li><li>出处：Frigo, Leiserson, Prokop, Ramachandran, <em>FOCS</em>, 1999。</li></ul>',6))])}const b=n(d,[["render",c]]);export{F as __pageData,b as default};
